(* [comment removed for export] *)
Lemma put_round7 : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p : Z) (cf : config),
  put_staticM H MX CX sp tp LB0 P E lo B p0 R bs mb ->
  put_at H MX CX 0x3d664 (ak_st 7) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p cf ->
  hs_SR H (put_res H MX CX ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p) cf.
Proof.
  intros until cf. intros STAT AT.
  eapply (hh_seq H HH); [eapply (put_arm37_SR _ 7 8 _ put_arm7); [lia | exact STAT | exact AT] |].
  intros cf' AT8. eapply put_round8; [exact STAT | exact AT8].
Qed.

